import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import yaml

app = Flask(__name__)
UPLOAD_DIR = '/tmp/reports'
os.makedirs(UPLOAD_DIR, exist_ok=True)

def load_config():
    config_path = os.environ.get('APP_CONFIG', '/etc/app/config.yaml')
    with open(config_path, 'r') as f:
        return yaml.safe_load(f)

@app.route('/api/v1/generate-report', methods=['POST'])
def generate_report():
    """Generate a PDF report from user-supplied template and data."""
    template_name = request.form.get('template', 'default')
    title = request.form.get('title', 'Report')
    author = request.form.get('author', 'System')
    output_format = request.form.get('format', 'pdf')

    # Validate format
    if output_format not in ('pdf', 'html', 'txt'):
        return jsonify({'error': 'Invalid format'}), 400

    # Sanitize template name to prevent directory traversal
    template_name = secure_filename(template_name)

    # Build the report generation command
    output_file = os.path.join(UPLOAD_DIR, f'report_{os.urandom(8).hex()}.{output_format}')

    # Use pandoc for conversion with user-supplied metadata
    cmd = f'pandoc /opt/templates/{template_name}.md -o {output_file} --metadata title="{title}" --metadata author="{author}"'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=UPLOAD_DIR
        )
        if result.returncode != 0:
            return jsonify({'error': 'Generation failed', 'detail': result.stderr.decode()[:200]}), 500

        return send_file(output_file, as_attachment=True)
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Timeout'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/v1/list-templates', methods=['GET'])
def list_templates():
    """List available report templates."""
    templates_dir = '/opt/templates'
    try:
        files = [f.replace('.md', '') for f in os.listdir(templates_dir) if f.endswith('.md')]
        return jsonify({'templates': files})
    except Exception:
        return jsonify({'templates': []})

@app.route('/api/v1/health', methods=['GET'])
def health():
    config = load_config()
    return jsonify({
        'status': 'healthy',
        'version': config.get('version', 'unknown'),
        'node': os.environ.get('HOSTNAME', 'unknown')
    })

@app.route('/api/v1/cleanup', methods=['POST'])
def cleanup():
    """Remove old generated reports."""
    auth = request.headers.get('X-Internal-Token')
    if auth != os.environ.get('INTERNAL_TOKEN'):
        return jsonify({'error': 'unauthorized'}), 403

    count = 0
    for f in os.listdir(UPLOAD_DIR):
        path = os.path.join(UPLOAD_DIR, f)
        if os.path.isfile(path):
            os.unlink(path)
            count += 1
    return jsonify({'removed': count})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
